--
-- Table structure for table `attendance_summaries`
--

DROP TABLE IF EXISTS `attendance_summaries`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attendance_summaries` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `employee_id` bigint unsigned NOT NULL,
  `summary_date` date NOT NULL,
  `shift_id` bigint unsigned DEFAULT NULL,
  `check_in_time` time DEFAULT NULL,
  `check_out_time` time DEFAULT NULL,
  `total_hours` decimal(5,2) NOT NULL DEFAULT '0.00',
  `overtime_hours` decimal(5,2) NOT NULL DEFAULT '0.00',
  `late_minutes` int NOT NULL DEFAULT '0',
  `early_out_minutes` int NOT NULL DEFAULT '0',
  `status` enum('present','absent','late','half_day','leave','holiday','off_day','missing_checkout','early_out') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'absent',
  `is_late` tinyint(1) NOT NULL DEFAULT '0',
  `is_overnight` tinyint(1) NOT NULL DEFAULT '0',
  `remarks` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `attendance_summaries_employee_id_summary_date_unique` (`employee_id`,`summary_date`),
  KEY `attendance_summaries_shift_id_foreign` (`shift_id`),
  KEY `attendance_summaries_summary_date_status_index` (`summary_date`,`status`)
) ENGINE=MyISAM AUTO_INCREMENT=11681 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

